1	import { ValidationError } from "./errors.js";
2	import { validateTopicFilter } from "./mqtt.js";
3	import { deepEqual, isPlainObject, readPath, validatePath } from "./values.js";
4	
5	export const OPERATORS = Object.freeze(["eq", "ne", "gt", "gte", "lt", "lte", "exists", "not_exists", "contains"]);
6	const UNARY_OPERATORS = new Set(["exists", "not_exists"]);
7	const RULE_KEYS = new Set(["id", "source", "device_id", "topic", "path", "operator", "value", "event"]);
8	const IDENTIFIER = /^[A-Za-z0-9][A-Za-z0-9._:-]{0,99}$/;
9	const EVENT_NAME = /^[a-z][a-z0-9_]{0,63}$/;
10	
11	export function identifier(value, label) {
12	  if (typeof value !== "string" || !IDENTIFIER.test(value)) {
13	    throw new ValidationError(`${label} must be 1 to 100 characters matching [A-Za-z0-9][A-Za-z0-9._:-]*`);
14	  }
15	  return value;
16	}
17	
18	/**
19	 * A rule is either shadow-scoped (it watches one device's shadow document) or
20	 * mqtt-scoped (its topic filter and the decoded payload form the document).
21	 */
22	export function parseRule(raw) {
23	  if (!isPlainObject(raw)) {
24	    throw new ValidationError("rule must be a JSON object");
25	  }
26	  for (const key of Object.keys(raw)) {
27	    if (!RULE_KEYS.has(key)) {
28	      throw new ValidationError(`unknown field ${key} in rule`);
29	    }
30	  }
31	  const rule = { id: identifier(raw.id, "rule id"), source: raw.source };
32	  if (raw.source === "shadow") {
33	    if (raw.topic !== undefined) {
34	      throw new ValidationError("a shadow rule must not declare a topic");
35	    }
36	    rule.device_id = identifier(raw.device_id, "device id");
37	  } else if (raw.source === "mqtt") {
38	    if (raw.device_id !== undefined) {
39	      throw new ValidationError("an mqtt rule must not declare a device id");
40	    }
41	    rule.topic = validateTopicFilter(raw.topic);
42	  } else {
43	    throw new ValidationError("source must be shadow or mqtt");
44	  }
45	  rule.path = validatePath(raw.path);
46	  if (!OPERATORS.includes(raw.operator)) {
47	    throw new ValidationError(`operator must be one of ${OPERATORS.join(", ")}`);
48	  }
49	  rule.operator = raw.operator;
50	  if (UNARY_OPERATORS.has(rule.operator)) {
51	    if (raw.value !== undefined) {
52	      throw new ValidationError(`operator ${rule.operator} must not declare a value`);
53	    }
54	  } else {
55	    if (raw.value === undefined) {
56	      throw new ValidationError(`operator ${rule.operator} requires a value`);
57	    }
58	    rule.value = structuredClone(raw.value);
59	  }
60	  if (typeof raw.event !== "string" || !EVENT_NAME.test(raw.event)) {
61	    throw new ValidationError("event must match [a-z][a-z0-9_]* and be at most 64 characters");
62	  }
63	  rule.event = raw.event;
64	  return rule;
65	}
66	
67	function ordered(actual, expected) {
68	  const bothNumbers = typeof actual === "number" && Number.isFinite(actual) && typeof expected === "number" && Number.isFinite(expected);
69	  const bothStrings = typeof actual === "string" && typeof expected === "string";
70	  return bothNumbers || bothStrings;
71	}
72	
73	function contains(actual, expected) {
74	  if (Array.isArray(actual)) {
75	    return actual.some((item) => deepEqual(item, expected));
76	  }
77	  if (typeof actual === "string" && typeof expected === "string") {
78	    return actual.includes(expected);
79	  }
80	  return false;
81	}
82	
83	export function evaluateCondition(rule, document) {
84	  const actual = readPath(document, rule.path);
85	  switch (rule.operator) {
86	    case "exists":
87	      return actual !== undefined;
88	    case "not_exists":
89	      return actual === undefined;
90	    case "eq":
91	      return actual !== undefined && deepEqual(actual, rule.value);
92	    case "ne":
93	      return actual !== undefined && !deepEqual(actual, rule.value);
94	    case "gt":
95	      return ordered(actual, rule.value) && actual > rule.value;
96	    case "gte":
97	      return ordered(actual, rule.value) && actual >= rule.value;
98	    case "lt":
99	      return ordered(actual, rule.value) && actual < rule.value;
100	    case "lte":
101	      return ordered(actual, rule.value) && actual <= rule.value;
102	    case "contains":
103	      return contains(actual, rule.value);
104	    default:
105	      throw new ValidationError(`unsupported operator ${rule.operator}`);
106	  }
107	}
108	
109	/** The value recorded with an emitted event; `undefined` is stored as null. */
110	export function matchedValue(rule, document) {
111	  const actual = readPath(document, rule.path);
112	  return actual === undefined ? null : actual;
113	}
