    assert.deepEqual(events.events[0], {
      sequence: 1,
      rule_id: "hot",
      event: "temperature_high",
      source: "shadow",
      device_id: "device-1",
      topic: null,
      value: 31,
      occurred_at: "2024-01-01T00:00:00.000Z",
